using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Demo6.Game;using Demo6.Core.Loot;
public static class StyleV4RestartCheck {
 public static object Run(){if(!EditorApplication.isPlaying)throw new Exception("Fresh Play required");var p=PlayerController.Instance;var inv=Inventory.Instance;var scene=SceneManager.GetActiveScene();var result=new{playing=EditorApplication.isPlaying,compiling=EditorApplication.isCompiling,scene=scene.path,dirty=scene.isDirty,bag=inv.BagCount,equipped=inv.Equipped.DisplayName,slots=GearSlots.SlotCount,gearIcons=GearBaseTable.All.Select(b=>new{id=b.Id,loaded=Resources.Load<Texture2D>("UI/Items/"+b.Id)!=null}).ToArray(),sprites=p.GetComponentsInChildren<SpriteRenderer>().Where(s=>s.sprite).Select(s=>new{name=s.name,sprite=s.sprite.name,path=AssetDatabase.GetAssetPath(s.sprite)}).ToArray(),modal=DungeonUi.Modal,saveFilesWritten=false};File.WriteAllText("검증/비주얼-개선-v4/after/restart-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}
}
